const item = $input.first().json;

let summary = '';
if (item.output && Array.isArray(item.output) && item.output[0]?.content?.[0]?.text) {
  summary = item.output[0].content[0].text;
} else if (typeof item.output === 'string') {
  summary = item.output;
} else if (item.text) {
  summary = item.text;
} else if (item.message?.content) {
  summary = item.message.content;
}

const sourceNames = $('Score & Rank Articles').first().json.sourceNames;
const today = new Date().toISOString().split('T')[0];

const digest = `# Weekly Competitor & Industry News Digest
**Date:** ${today}
**Sources:** ${sourceNames}
---

${summary}

---
_Generated automatically by the AI News Monitor workflow._`;

return [{ json: { digest, subject: `Weekly AI Industry Digest - ${today}` } }];

const activeSources = $('Get Active Sources').all().map(i => i.json);
const allSources = $('Get All Sources').all().map(i => i.json);
const fetched = $input.all();

const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
const cutoff = Date.now() - SEVEN_DAYS_MS;

function getEntryBlocks(xml) {
  return xml.match(/<item[\s\S]*?<\/item>/g) || xml.match(/<entry[\s\S]*?<\/entry>/g) || [];
}
function extractField(block, tag) {
  const m = block.match(new RegExp(`<${tag}[^>]*>(?:<!\\[CDATA\\[)?([\\s\\S]*?)(?:\\]\\]>)?<\\/${tag}>`));
  return m ? m[1].trim() : null;
}
function extractLink(block) {
  const hrefMatch = block.match(/<link[^>]*href=["']([^"']+)["']/);
  if (hrefMatch) return hrefMatch[1];
  return extractField(block, 'link');
}
function parseRecentEntries(xml) {
  const blocks = getEntryBlocks(xml);
  return blocks
    .map(block => {
      const title = extractField(block, 'title');
      const dateStr = extractField(block, 'pubDate') || extractField(block, 'published') || extractField(block, 'updated');
      const timestamp = dateStr ? Date.parse(dateStr) : NaN;
      const link = extractLink(block);
      return { title, timestamp, link };
    })
    .filter(e => e.title && (isNaN(e.timestamp) || e.timestamp >= cutoff))
    .sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
}

const updates = [];
const articles = [];

for (let i = 0; i < activeSources.length; i++) {
  const src = activeSources[i];
  const xml = (fetched[i] && fetched[i].json && fetched[i].json.data) || '';
  const recentEntries = parseRecentEntries(xml);
  const itemCount = recentEntries.length;

  const newSilent = itemCount > 0 ? 0 : (src.consecutive_silent_weeks || 0) + 1;
  let newActive = true;
  let newMonitoring = src.monitoring;

  if (itemCount === 0) {
    if (!src.monitoring && newSilent >= 2) {
      newMonitoring = true;
      const nextBackup = allSources
        .filter(s => s.pool === 'backup' && s.active === false)
        .sort((a, b) => (a.backup_rank || 0) - (b.backup_rank || 0))[0];
      if (nextBackup) {
        updates.push({ json: { isUpdateRow: true, id: nextBackup.id, active: true, consecutive_silent_weeks: 0, monitoring: false, replaced_source: src.name } });
      }
    } else if (src.monitoring && newSilent >= 4) {
      newActive = false;
      newMonitoring = false;
    }
  } else if (src.monitoring) {
    newMonitoring = false;
    const replacement = allSources.find(s => s.pool === 'backup' && s.active === true && s.replaced_source === src.name);
    if (replacement) {
      updates.push({ json: { isUpdateRow: true, id: replacement.id, active: false, consecutive_silent_weeks: 0, monitoring: false, replaced_source: '' } });
    }
  }

  updates.push({ json: { isUpdateRow: true, id: src.id, active: newActive, consecutive_silent_weeks: newSilent, monitoring: newMonitoring, replaced_source: src.replaced_source || '' } });

  for (const entry of recentEntries) {
    articles.push({ json: { isFetchResult: true, source: src.name, title: entry.title, link: entry.link || '', publishedAt: entry.timestamp ? new Date(entry.timestamp).toISOString() : null } });
  }

  if (recentEntries.length === 0) {
    articles.push({ json: { isFetchResult: true, isPlaceholder: true, source: src.name, title: null, link: '', publishedAt: null } });
  }
}

return [...updates, ...articles];

const items = $input.all().map(i => i.json);

const TOPICS = [
  'funding', 'raises', 'raised', 'acquisition', 'acquire', 'merger',
  'launch', 'launches', 'unveils', 'release', 'model', 'agent',
  'security', 'breach', 'vulnerability', 'lawsuit', 'regulation',
  'partnership', 'valuation', 'ipo', 'layoffs', 'hiring',
  'openai', 'anthropic', 'google', 'microsoft', 'meta', 'nvidia'
];

const now = Date.now();
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
const cutoff = now - SEVEN_DAYS_MS;

const sourceNames = [...new Set(items.map(i => i.source))];

const articles = items.filter(i => !i.isPlaceholder && i.title);

function scoreArticle(article) {
  const titleLower = article.title.toLowerCase();
  const keywordScore = TOPICS.reduce((sum, kw) => sum + (titleLower.includes(kw) ? 1 : 0), 0);
  const ts = article.publishedAt ? Date.parse(article.publishedAt) : cutoff;
  const recencyScore = Math.max(0, (ts - cutoff) / (now - cutoff)) * 3;
  return keywordScore + recencyScore;
}

const scored = articles
  .map(a => ({ ...a, score: Number(scoreArticle(a).toFixed(2)) }))
  .sort((a, b) => b.score - a.score);

const TOP_N = 15;
const topArticles = scored.slice(0, TOP_N);

return topArticles.map(a => ({
  json: {
    source: a.source,
    title: a.title,
    link: a.link,
    publishedAt: a.publishedAt,
    relevanceScore: a.score,
    sourceNames: sourceNames.join(', '),
    sourceCount: sourceNames.length,
    totalArticlesConsidered: articles.length,
    articlesSelected: topArticles.length
  }
}));

const items = $input.all();

function parseFacts(item) {
  const raw = item.json;
  let text = '';
  if (raw.output && Array.isArray(raw.output) && raw.output[0]?.content?.[0]?.text) {
    text = raw.output[0].content[0].text;
  } else if (typeof raw.output === 'string') {
    text = raw.output;
  } else if (raw.text) {
    text = raw.text;
  }
  text = text.trim().replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  try {
    return JSON.parse(text);
  } catch (e) {
    return { company: 'Unknown', event_type: 'other', amount: null, threat_level: 'low', one_line: text.slice(0, 200) };
  }
}

const facts = items.map((item, i) => {
  const parsed = parseFacts(item);
  const src = $('Score & Rank Articles').all()[i]?.json || {};
  return { ...parsed, source: src.source, title: src.title, link: src.link };
});

const sourceNames = $('Score & Rank Articles').first().json.sourceNames;
const sourceCount = $('Score & Rank Articles').first().json.sourceCount;

return [{
  json: {
    factsJson: JSON.stringify(facts, null, 2),
    factsArray: facts,
    sourceNames,
    sourceCount,
    articleCount: facts.length
  }
}];

